ee:variables.ee:set-variable:
%dw 2.0
output application/xml writeDeclaration=false
---
{
	subscribers: {
		subscriber_particulars: {
			subscriber_data @(action: payload.subscriber_particulars.subscriber_data.action): {
				business_unit: payload.subscriber_particulars.subscriber_data.business_unit,
				invoice_day: payload.subscriber_particulars.subscriber_data.invoice_day,
				market_type_name: payload.subscriber_particulars.subscriber_data.market_type_name,
				reason_code: payload.subscriber_particulars.subscriber_data.reason_code,
				period: payload.subscriber_particulars.subscriber_data.period,
				subscriber_type_name: payload.subscriber_particulars.subscriber_data.subscriber_type_name,
				term_type_name: payload.subscriber_particulars.subscriber_data.term_type_name,
				first_name: payload.subscriber_particulars.subscriber_data.first_name,
				last_name: payload.subscriber_particulars.subscriber_data.last_name,
				subscriber_name: payload.subscriber_particulars.subscriber_data.subscriber_name,
				subscriber_info4: payload.subscriber_particulars.subscriber_data.subscriber_info4,
				billing_entity_id: payload.subscriber_particulars.subscriber_data.billing_entity_id,
				start_date: {
					month: payload.subscriber_particulars.subscriber_data.start_date.month,
					day: payload.subscriber_particulars.subscriber_data.start_date.day,
					year: payload.subscriber_particulars.subscriber_data.start_date.year,
				},
				billable: payload.subscriber_particulars.subscriber_data.billable,
			},
			tax_plan_data @(action: payload.subscriber_particulars.tax_plan_data.action): {
				type_name: payload.subscriber_particulars.tax_plan_data.type_name,
				geocode: payload.subscriber_particulars.tax_plan_data.type_name,
			},
			billing_address_data @(action: payload.subscriber_particulars.billing_address_data.action): {
				bill_address1: payload.subscriber_particulars.billing_address_data.bill_address1,
				bill_address_geo_code: payload.subscriber_particulars.billing_address_data.bill_address_geo_code,
				bill_city: payload.subscriber_particulars.billing_address_data.bill_city,
				bill_country_code: payload.subscriber_particulars.billing_address_data.bill_country_code,
				bill_state_code: payload.subscriber_particulars.billing_address_data.bill_state_code,
				bill_billing_name: payload.subscriber_particulars.billing_address_data.bill_billing_name,
			},
			address_data @(action: payload.subscriber_particulars.address_data.action): {
				address1: payload.subscriber_particulars.address_data.address1,
				address_geo_code: payload.subscriber_particulars.address_data.address_geo_code,
				city: payload.subscriber_particulars.address_data.city,
				country_code: payload.subscriber_particulars.address_data.country_code,
				state_code: payload.subscriber_particulars.address_data.state_code,
			},
			currency_data @(action: payload.subscriber_particulars.currency_data.action): {
				currency_code:payload.subscriber_particulars.currency_data.currency_code
			},
			phone1_data @(action: payload.subscriber_particulars.phone1_data.action): {
				number1: payload.subscriber_particulars.phone1_data.number1
			},
			email_data @(action: payload.subscriber_particulars.email_data.action): {
				email_address: payload.subscriber_particulars.email_data.email_address
			},
			(payload.subscriber_particulars.characteristics_data map {
                    characteristics_data @(action: "add"): {
			            characteristic_group: $.characteristic_group,
			            characteristic_type: $.characteristic_type,
			            characteristic_value:  $.characteristic_value
                    }
                }),
			invoice_method_data @(action: payload.subscriber_particulars.invoice_method_data.action): {
				bill_or_statement: payload.subscriber_particulars.invoice_method_data.bill_or_statement,
				invoice_method_name: payload.subscriber_particulars.invoice_method_data.invoice_method_name,
				invoice_delivery_name: payload.subscriber_particulars.invoice_method_data.invoice_delivery_name,
				invoice_format_name: payload.subscriber_particulars.invoice_method_data.invoice_format_name,
				invoice_format_class_name: payload.subscriber_particulars.invoice_method_data.invoice_format_class_name
			}
		}
	}
}
